/* ---------- JS People ---------- */
function people(){const parts={kartlar:peopleCards,izin:peopleLeave,zimmet:peopleAssets,imza:peopleSign,onboarding:peopleOnboard,devir:peopleHandover};return head('İNSAN & MÜŞTERİ · JS PEOPLE','İnsanlar önce.','Özlük, izin hakkı, zimmet, imza seti, onboarding/offboarding ve devir planı. Ücret ve özlük verisi ayrı hassas yetkidir.',btn('Personel ekle','emp-new','primary','plus'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||peopleCards)()}`}
function peopleCards(){const list=state.employees.filter(e=>filter==='Tümü'||e.status===filter);return `<div class="toolbar">${tabs(['Tümü','Aktif','Ayrılıyor','Teyit bekliyor'])}</div><div class="project-grid">${list.map(e=>{const signed=Object.values(e.signatures).filter(v=>v==='İmzalandı').length;const eq=state.equipment.filter(q=>q.assigned===e.id);return `<article class="panel team-card"><div class="name-cell"><span class="avatar">${initials(e.name)}</span><div><h2>${esc(e.name)}</h2><small>${esc(e.title)} · ${esc(e.team)}</small></div></div><div class="actions" style="margin:10px 0">${badge(e.status)}${e.lastDay?badge(`Son gün ${date(e.lastDay)}`,'warn'):''}${badge(`İmza ${signed}/8`,signed===8?'success':'neutral')}</div>${kv([['Başlangıç',date(e.start)],['İzin',`${e.leaveTotal-e.leaveUsed} / ${e.leaveTotal} gün kalan`],['Zimmet',eq.length?eq.map(q=>q.name).join(', '):'—']])}<div class="actions">${btn('Kart','emp-open','sm','user',`data-id="${e.id}"`)}${e.status==='Teyit bekliyor'?btn('Statüyü teyit et','emp-confirm','sm primary','check',`data-id="${e.id}"`):''}</div></article>`}).join('')}</div>`}
function peopleLeave(){return tbl(['KİŞİ','HAK','KULLANILAN','KALAN','BEKLEYEN TALEP',''],state.employees.filter(e=>e.status!=='Teyit bekliyor').map(e=>`<tr><td>${esc(e.name)}</td><td>${e.leaveTotal}</td><td>${e.leaveUsed}</td><td><div class="health-bar">${meter((e.leaveTotal-e.leaveUsed)/Math.max(1,e.leaveTotal)*100)}<small>${e.leaveTotal-e.leaveUsed} gün</small></div></td><td>${state.leaves.filter(l=>l.person===e.id&&l.status==='Bekliyor').length}</td><td>${btn('İzin gir','leave-new','sm','plus')}</td></tr>`).join(''),'İzin hakları')}
function peopleAssets(){return tbl(['KİŞİ','ZİMMETLİ EKİPMAN','TARİH','ZİMMET FORMU'],state.employees.map(e=>{const eq=state.equipment.filter(q=>q.assigned===e.id);return `<tr><td>${esc(e.name)}</td><td>${eq.map(q=>esc(q.name)).join('<br>')||'—'}</td><td>${eq.map(q=>date(q.since)).join('<br>')||'—'}</td><td>${badge(e.signatures.zimmet)}</td></tr>`}).join(''),'Zimmet')}
function peopleSign(){return `<div class="banner">${ic('info')}<span>Ekim 2026 imza seti: 8 belge × ${state.employees.length} kişi. Durumu değiştirmek işlem kaydına yazılır; e-imza entegrasyonu üretim fazındadır.</span></div><div class="panel table-wrap" tabindex="0" role="region" aria-label="İmza seti"><table class="matrix"><thead><tr><th>KİŞİ</th>${SIGN_DOCS.map(([,l])=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${state.employees.map((e,i)=>`<tr><td>${esc(e.name)}<small>${esc(e.status)}</small></td>${SIGN_DOCS.map(([k])=>`<td><select class="sig ${e.signatures[k]==='İmzalandı'?'ok':e.signatures[k]==='Reddedildi'?'bad':''}" data-bind="employees.${i}.signatures.${k}" aria-label="${esc(e.name)} · ${k}">${['İmza bekliyor','Gönderildi','İmzalandı','Reddedildi'].map(s=>option(s,s,e.signatures[k])).join('')}</select></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="form-actions" style="justify-content:start;margin-top:12px">${btn('Tüm seti gönder','sign-send-all','primary','mail')}${btn('Durum CSV','sign-csv','','download')}</div>`}
function peopleOnboard(){const on=state.employees.filter(e=>e.onboarding?.length);const off=state.employees.filter(e=>e.offboarding?.length);const list=(e,key)=>`<article class="panel contract-card"><div class="card-top"><div><h2>${esc(e.name)}</h2><small class="muted">${esc(e.title)}${e.lastDay?` · son gün ${date(e.lastDay)}`:''}</small></div>${badge(`${e[key].filter(x=>x[1]).length}/${e[key].length}`,e[key].every(x=>x[1])?'success':'warn')}</div>${e[key].map((x,k)=>`<button class="field-item ${x[1]?'done':''}" data-action="ob-toggle" data-id="${e.id}" data-key="${key}" data-i="${k}" aria-pressed="${x[1]}"><span class="check ${x[1]?'done':''}">${x[1]?ic('check'):''}</span><span>${esc(x[0])}</span></button>`).join('')}</article>`;return `<section class="content-grid"><div><h2 style="margin-bottom:12px">Onboarding</h2>${on.map(e=>list(e,'onboarding')).join('')||'<p class="empty">Onboarding’de kimse yok.</p>'}</div><div><h2 style="margin-bottom:12px">Offboarding</h2>${off.map(e=>list(e,'offboarding')).join('')}</div></section>`}
function peopleHandover(){return `<div class="project-grid">${state.handover.map((h,hi)=>`<article class="panel contract-card"><div class="card-top"><div><h2>${esc(person(h.from))} → ${esc(person(h.to))}</h2><small class="muted">Devir ikizi aktif · son gün ${date(state.employees.find(e=>e.id===h.from)?.lastDay)}</small></div>${badge(`%${Math.round(h.items.filter(x=>x[1]).length/h.items.length*100)}`,'neutral')}</div>${meter(h.items.filter(x=>x[1]).length/h.items.length*100)}<div style="margin-top:10px">${h.items.map((x,k)=>`<button class="field-item ${x[1]?'done':''}" data-action="ho-toggle" data-id="${hi}" data-i="${k}" aria-pressed="${x[1]}"><span class="check ${x[1]?'done':''}">${x[1]?ic('check'):''}</span><span>${esc(x[0])}</span></button>`).join('')}</div></article>`).join('')}</div>`}
function empDetail(id){const e=state.employees.find(x=>x.id===id);if(!e)return;const i=state.employees.indexOf(e);openDialog(esc(e.name),`<div class="dialog-body"><div class="actions">${badge(e.status)}${badge(e.team,'neutral')}</div><div class="form-grid" style="margin-top:12px"><label class="form-field">Unvan<input data-bind="employees.${i}.title" value="${esc(e.title)}"></label><label class="form-field">Statü${sel(`employees.${i}.status`,['Aktif','Ayrılıyor','Teyit bekliyor','Ayrıldı'],e.status,'data-rerender')}</label><label class="form-field">İzin hakkı<input type="number" data-bind="employees.${i}.leaveTotal" data-number value="${e.leaveTotal}"></label><label class="form-field">Kullanılan<input type="number" data-bind="employees.${i}.leaveUsed" data-number value="${e.leaveUsed}"></label></div><p class="small muted">Ücret/özlük alanları bu rolde gösterilmez (ayrı hassas yetki).</p><h3>İmza seti</h3><div class="chip-row">${SIGN_DOCS.map(([k,l])=>`<span class="chip ${e.signatures[k]==='İmzalandı'?'ok':''}">${l}: ${e.signatures[k]}</span>`).join('')}</div><div class="form-actions">${btn('Kapat','close','primary','check')}</div></div>`)}

/* ---------- JS Hire ---------- */
const hireStages=['Başvuru','Görüşme','Case','Teklif'];
function hire(){const parts={pozisyonlar:hirePositions,aday:hireKanban,puan:hireScore,teklif:hireOffer,portal:hirePortal};return head('İNSAN & MÜŞTERİ · JS HIRE','Doğru insanı bul.','Açık pozisyonlar, aday kanbanı, CV/portfolyo, puan formu, teklif ve JS People’a aktarım. Aday portalı ayrık ve rızaya dayalı.',btn('Yeni pozisyon','pos-new','primary','plus'))+`<div class="toolbar">${subnav()}</div>${(parts[sub]||hirePositions)()}`}
function hirePositions(){return tbl(['POZİSYON','EKİP','TÜR','AÇILIŞ','BAŞVURU','HAVUZDA','İŞE ALIM YÖNETİCİSİ','DURUM',''],state.positions.map(p=>`<tr><td><strong>${esc(p.title)}</strong></td><td>${esc(p.team)}</td><td>${esc(p.type)}</td><td>${date(p.opened)}</td><td>${p.applicants}</td><td>${state.candidates.filter(c=>c.position===p.id).length}</td><td>${esc(person(p.hiringManager))}</td><td>${badge(p.status)}</td><td><div class="actions">${btn('İlan linki','copy','sm','copy',`data-id="https://jobsstudio.co/kariyer/${p.id}"`)}${p.status==='Açık'?btn('Kapat','pos-close','sm','close',`data-id="${p.id}"`):''}</div></td></tr>`).join(''),'Açık pozisyonlar')}
const totalScore=c=>Object.values(c.score).reduce((a,b)=>a+b,0);
function hireKanban(){const pos=ui.pos||'';return `<div class="toolbar"><label class="form-field" style="min-width:220px">Pozisyon<select data-ui-sel="pos"><option value="">Tümü</option>${state.positions.map(p=>option(p.id,p.title,pos)).join('')}</select></label></div>${kanban(hireStages,state.candidates.filter(c=>!pos||c.position===pos),c=>`<button class="kcard-title" data-action="cand-open" data-id="${c.id}">${esc(c.name)}</button><small>${esc(state.positions.find(p=>p.id===c.position)?.title)} · ${esc(c.source)}</small><div class="actions" style="margin-top:6px">${badge(`Puan ${totalScore(c)}/20`,totalScore(c)>=14?'success':'neutral')}<a class="chip" href="${esc(c.cv)}" target="_blank" rel="noopener">CV</a>${c.portfolio?`<a class="chip" href="${esc(c.portfolio)}" target="_blank" rel="noopener">Portfolyo</a>`:''}</div>${c.stage==='Teklif'?`<div class="actions" style="margin-top:6px">${btn('Teklif & People’a aktar','cand-hire','sm primary','people',`data-id="${c.id}"`)}</div>`:''}`,'cand-move',c=>c.stage)}`}
function hireScore(){const c=state.candidates.find(x=>x.id===ui.cand)||state.candidates[0];const i=state.candidates.indexOf(c);const crit=[['portfolio','Portfolyo / iş örnekleri'],['interview','Görüşme'],['case','Case çalışması'],['fit','Ekip uyumu']];return `<div class="toolbar"><label class="form-field" style="min-width:240px">Aday<select data-ui-sel="cand">${state.candidates.map(x=>option(x.id,`${x.name} · ${state.positions.find(p=>p.id===x.position)?.title}`,c.id)).join('')}</select></label>${badge(`Toplam ${totalScore(c)}/20`,totalScore(c)>=14?'success':'neutral')}</div><section class="panel settings-section"><h2>Puan formu · ${esc(c.name)}</h2><p>1–5 ölçeği; puanlar insan değerlendirmesidir, AI otomatik karar vermez.</p>${crit.map(([k,l])=>`<div class="toggle-row"><div>${l}<small>${c.score[k]||'—'} / 5</small></div><div class="score-dots">${[1,2,3,4,5].map(n=>`<button class="skill-dot ${c.score[k]>=n?'l5':'l0'}" data-action="cand-score" data-id="${c.id}" data-k="${k}" data-n="${n}" aria-label="${l}: ${n}">${n}</button>`).join('')}</div></div>`).join('')}<label class="form-field" style="margin-top:12px">Not<textarea data-bind="candidates.${i}.note" maxlength="400">${esc(c.note||'')}</textarea></label></section>`}
function hireOffer(){const offers=state.candidates.filter(c=>c.stage==='Teklif');return `<div class="project-grid">${offers.map(c=>`<article class="panel contract-card"><div class="card-top"><div><h2>${esc(c.name)}</h2><small class="muted">${esc(state.positions.find(p=>p.id===c.position)?.title)} · puan ${totalScore(c)}/20</small></div>${badge('Teklif')}</div>${kv([['Başlangıç','2026-11-02'],['Sözleşme','Belirsiz süreli'],['Onboarding','Hesap, ekipman, imza seti (8 belge)']])}<div class="actions">${btn('Teklifi gönder','cand-offer','sm','mail',`data-id="${c.id}"`)}${btn('Kabul → JS People’a aktar','cand-hire','sm primary','people',`data-id="${c.id}"`)}</div></article>`).join('')||'<p class="empty">Teklif aşamasında aday yok.</p>'}</div>`}
function hirePortal(){return `<div class="banner">${ic('shield')}<span>Aday portalı ayrı bir yüzeydir: aday yalnızca kendi başvurusunu, aşamasını ve belgelerini görür; iç notlar ve puanlar görünmez. Veri saklama 12 ay (rıza).</span></div>${tbl(['ADAY','PORTAL LİNKİ','AŞAMA','SON GİRİŞ',''],state.candidates.map(c=>`<tr><td>${esc(c.name)}</td><td class="mono">https://kariyer.jobsstudio.co/a/${c.id}</td><td>${badge(c.stage)}</td><td>—</td><td>${btn('Linki kopyala','copy','sm','copy',`data-id="https://kariyer.jobsstudio.co/a/${c.id}"`)}</td></tr>`).join(''),'Aday portalı')}`}
function candDetail(id){const c=state.candidates.find(x=>x.id===id);if(!c)return;openDialog(esc(c.name),`<div class="dialog-body"><div class="actions">${badge(c.stage)}${badge(state.positions.find(p=>p.id===c.position)?.title,'neutral')}${badge(`Puan ${totalScore(c)}/20`)}</div>${kv([['Kaynak',c.source],['CV',`<a href="${esc(c.cv)}" target="_blank" rel="noopener">${esc(c.cv)}</a>`],['Portfolyo',c.portfolio?`<a href="${esc(c.portfolio)}" target="_blank" rel="noopener">${esc(c.portfolio)}</a>`:'—'],['Sonraki adım',date(c.next)]])}<div class="form-actions">${btn('Puan formu','cand-score-open','','star',`data-id="${c.id}"`)}${btn('Kapat','close','primary','check')}</div></div>`)}

/* ---------- JS Client Portal ---------- */
function portal(){const parts={isler:portalWork,onaylar:portalApprovals,talep:portalRequest,dosyalar:portalFiles,raporlar:portalReports,sohbet:portalChat};return head('İNSAN & MÜŞTERİ · JS CLIENT PORTAL','Projem ne durumda?',`${isClient()?'Yalnızca size görünür içerik: açık işler, onaylar, talepler, onaylı teslimler, raporlar ve faturalar.':'Müşteri gözünden görünüm. Finans, iç not ve maaş verisi portalda yoktur.'}`,btn('Talep aç','portal-request','primary','plus'))+`<div class="toolbar">${subnav()}</div>${isClient()?'':`<div class="banner">${ic('eye')}<span>Önizleme: ${portalBrands().map(b=>client(b)).join(' + ')} portalını iç rolde görüyorsun. Müşteri rolüyle giriş yapmak için “Rolü değiştir”.</span></div>`}${(parts[sub]||portalWork)()}`}
const portalBrands=()=>isClient()?clientBrands():['c_anova','c_wellana'];
const pScope=id=>portalBrands().includes(id);
function portalWork(){const ps=state.projects.filter(p=>pScope(p.client)&&p.client_visible!==false);const ts=state.tasks.filter(t=>t.client_visible&&ps.some(p=>p.id===t.project)&&!t.done);return `<section class="metrics">${metric('Açık projeler',ps.filter(p=>p.status!=='Tamamlandı').length,'','projects')}${metric('Açık işler',ts.length,'size görünür görevler','tasks')}${metric('Onay bekleyen',state.approvals.filter(a=>a.kind==='Müşteri kararı'&&a.status==='Bekliyor'&&pScope(project(a.project)?.client)).length,'','approvals')}${metric('Teslimler',state.assets.filter(a=>pScope(a.client)&&a.status==='Onaylı').length,'onaylı dosya','files')}</section><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Projeler</h2></div><div class="panel-body">${ps.map(projectRow).join('')}</div></div><div class="panel"><div class="panel-header"><h2>Açık işler</h2></div><div class="panel-body">${ts.map(taskRow).join('')||'<p class="empty">Açık iş yok.</p>'}</div></div></section>`}
function portalApprovals(){const items=state.approvals.filter(a=>a.kind==='Müşteri kararı'&&pScope(project(a.project)?.client));const social=state.social.filter(s=>pScope(s.client)&&s.stage==='Müşteri onayı');const vids=state.reviews.filter(r=>pScope(r.client)&&r.status!=='Onaylandı');return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Sosyal takvim · toplu onay</h2>${badge(`${social.length} içerik`)}</div><div class="panel-body">${social.map(s=>`<div class="session-row"><div>${esc(s.text)}<small>${esc(client(s.client))} · ${esc(s.channel)} · ${s.day} Ekim</small></div>${badge(s.stage)}</div>`).join('')||'<p class="empty">Onay bekleyen içerik yok.</p>'}${social.length?`<div class="form-actions" style="justify-content:start">${btn('Tümünü onayla','portal-social-approve','primary','check')}${btn('Revize iste','portal-social-revise','','refresh')}</div>`:''}</div></div><div class="panel"><div class="panel-header"><h2>Video sürümleri</h2></div><div class="panel-body">${vids.map(r=>`<div class="session-row"><div>${esc(r.name)}<small>${r.current} · ${esc(r.status)} · tur ${r.rounds.used}/${r.rounds.included}</small></div>${btn('İncele','review-open','sm','review',`data-id="${r.asset}"`)}</div>`).join('')||'<p class="empty">Bekleyen sürüm yok.</p>'}</div></div></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Karar kuyruğu</h2></div><div class="panel-body">${items.map(a=>`<div class="session-row"><div>${esc(a.name)}<small>${esc(a.desc)}</small></div><div class="actions">${badge(a.status)}${a.status==='Bekliyor'?btn('Onayla','approve','sm primary','check',`data-id="${a.id}" data-value="Onaylandı"`)+btn('Revize','approve','sm','refresh',`data-id="${a.id}" data-value="Revizyon"`):''}</div></div>`).join('')||'<p class="empty">Karar yok.</p>'}</div></section>`}
function portalRequest(){return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Yeni talep · brief 5 unsur</h2></div><div class="panel-body"><form id="request-form" class="form-grid"><label class="form-field">Marka<select name="client">${portalBrands().map(b=>option(b,client(b))).join('')}</select></label><label class="form-field">Başlık<input name="title" required maxlength="90"></label><label class="form-field full">01 · Neyi değiştirmek istiyoruz?<textarea name="goal" required></textarea></label><label class="form-field full">02 · Kimin için?<textarea name="audience" required></textarea></label><label class="form-field full">03 · Beklenen çıktılar<textarea name="outputs" required></textarea></label><label class="form-field full">04 · Başarıyı nasıl okuyacağız?<textarea name="success" required></textarea></label><label class="form-field full">05 · Sınırlar & teslim<textarea name="limits" required></textarea></label><div class="form-actions" style="grid-column:1/-1;justify-content:start"><button class="button primary" type="submit">Talebi gönder ${ic('check')}</button></div></form></div></div><div class="panel"><div class="panel-header"><h2>Taleplerim</h2></div><div class="panel-body">${state.requests.filter(r=>pScope(r.client)).map(r=>`<div class="session-row"><div>${esc(r.title)}<small>${esc(client(r.client))} · ${esc(r.created)}</small></div>${badge(r.status)}</div>`).join('')}</div></div></section>`}
function portalFiles(){const files=state.assets.filter(a=>pScope(a.client)&&['Onaylı','Arşiv'].includes(a.status));return tbl(['DOSYA','PROJE','TÜR','TARİH',''],files.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(project(a.project)?.name||'—')}</td><td>${esc(a.type)}</td><td>${date(a.created)}</td><td><div class="actions"><button class="button sm" data-action="file-preview" data-id="${a.id}">Önizle</button>${btn('İndir (imzalı link)','portal-download','sm','download',`data-id="${a.id}"`)}</div></td></tr>`).join(''),'Onaylı teslimler','Yalnızca onaylı teslimler listelenir; link 15 dakika geçerli imzalı URL’dir.')}
function portalReports(){const docs=state.documents.filter(d=>d.type==='Rapor'&&pScope(d.client));const inv=state.invoices.filter(i=>pScope(i.client));return `<section class="content-grid"><div class="panel"><div class="panel-header"><h2>Aylık raporlar</h2></div><div class="panel-body">${docs.map(d=>`<div class="session-row"><div>${esc(d.name)}<small>${d.pages} sayfa · ${esc(d.updated)}</small></div>${btn('Aç','present-pdf','sm','download',`data-id="${d.id}"`)}</div>`).join('')||'<p class="empty">Rapor yok.</p>'}</div></div><div class="panel"><div class="panel-header"><h2>Faturalar (müşteri yüzü)</h2></div><div class="panel-body">${inv.map(i=>`<div class="session-row"><div>${i.id}<small>${date(i.due)} vade · ${money(i.amount)}</small></div>${badge(i.status)}</div>`).join('')}</div></div></section>`}
function portalChat(){return `<section class="panel chat-panel"><div class="panel-header"><h2>JS Asistan · “Projem ne durumda?”</h2>${badge('Simüle · yalnızca portal verisi','ai')}</div><div class="panel-body"><div class="chat">${state.chat.map(m=>`<div class="bubble ${m.who}"><p>${esc(m.text)}</p><small>${esc(m.at)}</small></div>`).join('')}</div><form id="chat-form" class="chat-form"><input name="q" placeholder="Örn. Ekim görselleri ne zaman hazır?" aria-label="Soru" required><button class="button primary" type="submit">Sor ${ic('chat')}</button></form><p class="small muted">Asistan yalnızca müşteriye görünür kayıtları özetler; finans, iç not ve ekip verisi görmez.</p></div></section>`}
function portalAnswer(q){const t=q.toLocaleLowerCase('tr');const ps=state.projects.filter(p=>pScope(p.client));if(/film|video|kurgu/.test(t)){const r=state.reviews.find(x=>pScope(x.client));return r?`${r.name}: ${r.current} ${r.status.toLocaleLowerCase('tr')} · ${r.versions.at(-1).comments.filter(c=>!c.internal&&!c.resolved).length} açık müşteri yorumu · final teslim ${date(project(r.project)?.due)}.`:'Video işi bulunamadı.'}if(/görsel|sosyal|post|takvim/.test(t)){const s=state.social.filter(x=>pScope(x.client)&&x.month==='2026-10');return `Ekim takviminde ${s.length} içerik: ${s.filter(x=>x.stage==='Yayın').length} yayında, ${s.filter(x=>x.stage==='Müşteri onayı').length} onayınızı bekliyor, ${s.filter(x=>['Fikir','Metin','Görsel','İç onay'].includes(x.stage)).length} üretimde.`}if(/fatura|ödeme/.test(t)){const inv=state.invoices.filter(i=>pScope(i.client)&&i.status!=='Ödendi');return `Açık ${inv.length} fatura: ${inv.map(i=>`${i.id} ${money(i.amount)} (${date(i.due)})`).join(', ')}.`}if(/talep/.test(t))return `Açık talepleriniz: ${state.requests.filter(r=>pScope(r.client)&&r.status!=='Tamamlandı').map(r=>r.title).join(', ')||'yok'}.`;return `${ps.length} projeniz var: ${ps.map(p=>`${p.name.split(' · ')[1]||p.name} %${progress(p)}`).join(', ')}. Onayınızı bekleyen ${state.approvals.filter(a=>a.kind==='Müşteri kararı'&&a.status==='Bekliyor'&&pScope(project(a.project)?.client)).length} karar var.`}

/* ---------- JS Insights ---------- */
function insights(){const parts={huni:insFunnel,kapasite:insCapacity,marj:insMargin,saglik:insHealth,kurul:insBoard,veri:insData};return head('ZEKÂ · JS INSIGHTS','Ne oluyor, neden oluyor.','Satış hunisi, kapasite, marj, müşteri sağlığı, kurul KPI ve veri kalitesi. Her grafik kaynağına bağlıdır; güven rozeti veri eksikliğini gösterir.',btn('Haftalık özet (PDF / e-posta)','insights-weekly','primary','download'))+`<div class="toolbar">${subnav()}<span class="badge ${state.expenses.some(x=>x.status==='Eksik')?'warn':'success'}">Veri güveni: ${state.expenses.some(x=>x.status==='Eksik')?'ORTA · 1 eksik gider':'YÜKSEK'}</span></div>${(parts[sub]||insFunnel)()}`}
const chartPanel=(title,body,note='')=>`<section class="panel" style="margin-bottom:20px"><div class="panel-header"><h2>${title}</h2>${note?`<span class="small muted">${note}</span>`:''}</div><div class="panel-body">${body}</div></section>`;
function insFunnel(){const by=s=>state.leads.filter(l=>l.stage===s).length;return chartPanel('Lead → Görüşme → Teklif → Kazanım',svgBars(leadStages.map(s=>[s,by(s),s==='Kaybedildi'?'warn':'']),{label:'Satış hunisi'}),'Kaynak: JS CRM lead’leri')+chartPanel('Teklif çevrim süresi (gün)',svgLine([{name:'Çevrim',data:[18,14,21,12,9,11]}],{labels:['May','Haz','Tem','Ağu','Eyl','Eki'],label:'Teklif çevrim süresi'})+legend(['Teklif → karar gün']))}
function insCapacity(){return chartPanel('Haftalık planlanan saat · ekip toplamı / kapasite',svgLine([{name:'Planlanan',data:weeks.map((_,i)=>state.team.reduce((s,t)=>s+(state.capacity[t.id]?.[i]||0),0))},{name:'Kapasite',data:weeks.map(()=>state.team.length*40)}],{labels:weeks.map(w=>w.split(' ')[0]),label:'Kapasite'})+legend(['Planlanan','Kapasite']),'Kaynak: JS Resources')+chartPanel('Kişi başı doluluk (bu hafta)',svgBars(state.team.map(t=>[t.id,Math.round(t.hours/40*100),t.hours>40?'warn':'']),{unit:'%',label:'Doluluk'}))}
function insMargin(){return chartPanel('Proje marjı (%)',svgBars(state.projects.map(p=>[p.name.split(' · ')[0].slice(0,8),projectMargin(p).margin,projectMargin(p).margin<20?'warn':'']),{unit:'%',label:'Marj'}),'Saat × maliyet + direkt gider')+chartPanel('Tahmin vs gerçek saat',svgBars([['Wellana',42,''],['Anova film',31,''],['Badem',12,''],['Edit',8,'']].map(([n,v,c])=>[n,v,c]),{label:'Tahmin sapması %'}),'Pozitif = fazla harcanan')}
function insHealth(){return chartPanel('Müşteri sağlık skoru',svgBars(state.clients.filter(c=>!c.internal).slice(0,12).map(c=>[c.name.slice(0,7),c.health,c.health<60?'warn':'']),{label:'Sağlık'}),'Etkileşim, tahsilat, revize sayısı ve yazışma sıklığı')+tbl(['MARKA','SKOR','RİSK SİNYALİ','ÖNERİ'],state.clients.filter(c=>c.health<65).map(c=>`<tr><td>${esc(c.name)}</td><td>${c.health}</td><td>${c.id==='c_wellana'?'Etkileşim düşüşü, yenileme yaklaşıyor':c.id==='c_opsin'?'Gecikmiş fatura + revize itirazı':'Yeni ilişki'}</td><td>${c.id==='c_wellana'?'CEO kararı: ek paket teklifi':c.id==='c_opsin'?'Revize teslimi + tahsilat görüşmesi':'Teklif takibi'}</td></tr>`).join(''),'Risk listesi')}
function insBoard(){const b=state.board.kpi;return `<section class="metrics">${metric('Runway',`${b.runway} <small>gün</small>`,'CFO','finance')}${metric('Seviye 0 oranı',`%${b.level0}`,'otomatik uygulanan kararlar','automation')}${metric('Kurucuya giden',`${pendingDecisions()} <small>/ hafta</small>`,'hedef ≤ 3','profile')}${metric('Açık onay',state.approvals.filter(a=>a.status==='Bekliyor').length,'Onay Merkezi','approvals')}</section>${chartPanel('Haftalık karar sayısı',svgLine([{name:'Seviye 0',data:[9,11,8,12,10,9]},{name:'Kurucuya',data:[3,2,4,2,3,4]}],{labels:['W37','W38','W39','W40','W41','W42'],label:'Kararlar'})+legend(['Seviye 0 (otomatik)','Kurucuya giden']))}`}
function insData(){const checks=[['Gider tutarı eksik',state.expenses.filter(x=>x.status==='Eksik').length,'JS Finance → Giderler'],['Sorumlusuz görev',state.tasks.filter(t=>!t.owner).length,'JS Work'],['Sözleşmesiz aktif marka',state.clients.filter(c=>c.status==='Aktif'&&!c.internal&&!state.contracts.some(x=>x.client===c.id)).length,'JS CRM → Sözleşmeler'],['KVKK izinsiz kişi',state.contacts.filter(k=>!k.kvkk).length,'JS CRM → Kişiler'],['Doğrulanmamış yedek',state.settings.data.verifyOk?0:1,'Admin → System Health'],['İmza bekleyen belge',state.employees.reduce((s,e)=>s+Object.values(e.signatures).filter(v=>v!=='İmzalandı').length,0),'JS People → İmza seti']];return tbl(['KONTROL','SAYI','DURUM','NEREDE'],checks.map(([n,c,w])=>`<tr><td>${n}</td><td>${c}</td><td>${c?badge('Eksik'):badge('Tam')}</td><td>${w}</td></tr>`).join(''),'Veri kalitesi','Rapor güveni: eksik veri 0 sayılmaz; etkilenen metrikler “kısmi” etiketlenir.')}

/* ---------- Onay Merkezi ---------- */
const approvalKinds=['Tümü','İçerik','Bütçe','Kapsam dışı','Müşteri kararı','Yetki değişikliği','İzin'];
function approvals(){const parts={kuyruk:approvalQueue,politika:approvalPolicy};return head('YÖNETİM & SİSTEM · ONAY MERKEZİ','Doğru karar, doğru anda.','Tek kuyruk: içerik, bütçe/harcama (≤5k / 5–25k / >25k), kapsam dışı iş, müşteri kararı, yetki değişikliği. request → policy check → authorized human action → result → immutable audit.')+`<div class="toolbar">${subnav()}</div>${(parts[sub]||approvalQueue)()}`}
function approvalQueue(){let as=state.approvals.filter(a=>isClient()?(a.kind==='Müşteri kararı'&&inScope(project(a.project)?.client)):true).filter(a=>filter==='Tümü'||a.kind===filter);const pending=as.filter(a=>a.status==='Bekliyor'),doneList=as.filter(a=>a.status!=='Bekliyor');const card=a=>{const timeout=a.status==='Bekliyor'&&daysFromToday(a.deadline)<0;return `<article class="panel approval-card"><div class="approval-art">${esc((project(a.project)?client(project(a.project).client):'JS')[0])}<span style="color:#ff4200">.</span></div><div class="description"><div class="actions">${badge(a.kind,a.kind==='Yetki değişikliği'?'danger':a.kind==='Kapsam dışı'?'warn':'neutral')}${badge(a.status)}${a.amount?badge(`${money(a.amount)} · ${approvalLevel(a.amount)}`,'neutral'):''}${timeout?badge('Zaman aşımı → vekile düştü','danger'):a.status==='Bekliyor'?badge(`Son ${date(a.deadline)}`,'neutral'):''}${a.delegate?badge(`Vekil: ${person(a.delegate)}`,'warn'):''}</div><h3>${esc(a.name)} <span class="muted small">${esc(a.version)}</span></h3><p>${esc(project(a.project)?.name||'—')} · ${esc(a.desc)}</p><p class="small muted">Talep: ${esc(person(a.by))} · ${esc(a.requested)}${a.feedback?` · Karar notu: ${esc(a.feedback)}`:''}</p></div><div class="actions">${a.status==='Bekliyor'?btn('İncele & karar ver','approval','','arrow',`data-id="${a.id}"`):btn('Geri al','approve','sm','refresh',`data-id="${a.id}" data-value="Bekliyor"`)}</div></article>`};return `<div class="toolbar">${tabs(approvalKinds)}</div><h2 style="margin:4px 0 12px">Bekleyen <span class="muted small">${pending.length}</span></h2>${pending.map(card).join('')||'<p class="empty">Bekleyen onay yok.</p>'}<h2 style="margin:24px 0 12px">Karara bağlanan <span class="muted small">${doneList.length}</span></h2>${doneList.slice(0,8).map(card).join('')||'<p class="empty">—</p>'}`}
function approvalPolicy(){const s=state.settings.structure;return `<div class="level-grid"><div class="level"><strong>Seviye 0 · Otomatik</strong>≤ ${money(s.level0Max)}<p class="small muted" style="margin-top:8px">Kural içinde kalan harcama ve içerik aşaması; audit’e yazılır, insan onayı istenmez.</p></div><div class="level"><strong>Seviye 1 · PM / Account</strong>${money(s.level0Max)} – ${money(s.level1Max)}<p class="small muted" style="margin-top:8px">Zaman aşımı 48 saat → vekile düşer (izinli kişinin görevleri tarih sınırlı devredilir).</p></div><div class="level"><strong>Seviye 2 · Kurucu</strong>&gt; ${money(s.level1Max)}<p class="small muted" style="margin-top:8px">MFA zorunlu. Yetki değişikliği ve kapsam dışı iş her zaman bu seviyededir.</p></div></div><section class="panel settings-section" style="margin-top:20px"><h2>Politika</h2><ul class="meeting-list"><li>${ic('check')}<span>Kapsam dışı iş → Account + şirket yetkilisi; gerekiyorsa müşteri değişiklik emri.</span></li><li>${ic('check')}<span>Müşteri tasarım/video kararı → portal üzerinden; audit müşteri kimliğiyle yazılır.</span></li><li>${ic('check')}<span>Yetki değişikliği → owner onayı + MFA; own-role escalation engeli.</span></li><li>${ic('check')}<span>AI hiçbir onayı tamamlayamaz; yalnızca önerir ve hazırlar.</span></li></ul><div class="form-actions" style="justify-content:start">${btn('Eşikleri düzenle (Admin → Yapı)','goto','','settings','data-id="admin/ayar-yapi"')}</div></section>`}
function approvalDialog(id){const a=state.approvals.find(x=>x.id===id);if(!a)return;openDialog(`${esc(a.name)}`,`<div class="dialog-body"><div class="actions">${badge(a.kind)}${badge(a.status)}${a.amount?badge(approvalLevel(a.amount),'neutral'):''}</div><p style="margin-top:12px">${esc(a.desc)}</p>${a.kind==='İçerik'?`<div class="cover" style="height:140px;border-radius:12px;padding:22px;background:var(--blue);color:white;display:flex;align-items:center;font-size:26px;margin:12px 0">${esc(project(a.project)?.name||a.name)}<span style="color:#ff4200">.</span></div>`:''}<p class="small muted">Politika: ${a.kind==='Yetki değişikliği'?'Owner + MFA':a.kind==='Kapsam dışı'?'Account + yetkili; müşteri değişiklik emri':a.amount?approvalLevel(a.amount):'Yetkili karar verici'} · Zaman aşımı: ${date(a.deadline)} → vekil</p><form id="approval-form" data-id="${a.id}"><label class="form-field" style="margin-top:12px">Karar notu (ret/revizyon için zorunlu)<textarea name="feedback" maxlength="800"></textarea></label><label class="form-field">Vekâlet ver<select name="delegate"><option value="">—</option>${state.team.filter(t=>t.id!==account().person).map(t=>option(t.id,t.name)).join('')}</select></label><div class="form-actions"><button class="button" type="submit" name="decision" value="Vekâlet">Vekâlet ver</button><button class="button" type="submit" name="decision" value="Reddedildi">Reddet</button><button class="button primary" type="submit" name="decision" value="Onaylandı">Onayla ${ic('check')}</button></div></form></div>`)}

/* ---------- JS Core · Admin ---------- */
function admin(){const parts={exec:adminExec,people:adminPeople,companies:adminCompanies,workforce:()=>adminLink('Workforce & Resources','Ekip yükleri, izin, proje kapasitesi ve ekipman JS Resources ve JS People’da yönetilir.',[['resources/kapasite','Kapasite ısı haritası'],['resources/izin','İzin takvimi'],['resources/ekipman','Ekipman & zimmet'],['people/kartlar','Personel kartları']]),approvals:()=>adminLink('Approvals Hub','Fiyat, kapsam dışı iş, paylaşım, satın alma ve müşteri kararları tek kuyrukta; zaman aşımı ve vekil kuralları Onay Merkezi’nde.',[['approvals/kuyruk',`Onay kuyruğu (${state.approvals.filter(a=>a.status==='Bekliyor').length} bekliyor)`],['approvals/politika','Politika & eşikler']]),integrations:()=>adminLink('Integrations Center','Bağlı Google hesapları ve API kapsamı, yenileme hataları, son senkron, webhook geçmişi JS Connect’te.',[['integrations/entegrasyonlar',`Entegrasyonlar (${state.integrations.filter(i=>i.status==='Hata').length} hata)`],['integrations/mcp','MCP sunucuları'],['integrations/api','API & Webhook’lar']]),security:adminSecurity,automation:()=>adminLink('Automation Center','Otomasyon listesi, tetikleme, çalıştırma geçmişi, hata, tekrar deneme ve event replay JS Automation’da.',[['automations',`Olay akışı & çalıştırmalar (${state.runs.filter(r=>r.status==='Hata').length} hata)`]]),billing:adminBilling,health:adminHealth,privacy:adminPrivacy,flags:adminFlags,'ayar-genel':settingsGeneral,'ayar-bildirimler':settingsNotif,'ayar-yapi':settingsStructure,'ayar-ai':settingsAi,'ayar-gorunum':settingsLook,'ayar-veri':settingsData};return head('YÖNETİM & SİSTEM · JS CORE · ADMIN','Admin Control Center.','12 zorunlu admin ekranı + Ayarlar. Platform super admin müşteri verisini varsayılan olarak okuyamaz; yüksek riskli işlemler MFA ve onaya tabidir.',`<label class="form-field" style="min-width:220px">Organizasyon<select data-bind="session.org" data-rerender>${state.orgs.map(o=>option(o.id,o.name,state.session.org)).join('')}</select></label>`)+`<div class="settings-layout">${adminNav()}<div>${(parts[sub]||adminExec)()}</div></div>`}
function adminNav(){const acc=subTabs.admin.filter(t=>!t[0].startsWith('ayar-')),ay=subTabs.admin.filter(t=>t[0].startsWith('ayar-'));const item=([id,label])=>`<button role="tab" class="${sub===id?'active':''}" aria-selected="${sub===id}" data-action="sub" data-id="${id}"><span class="lbl">${label.replace('Ayarlar · ','')}</span></button>`;return `<div class="subnav" role="tablist" aria-label="Admin bölümleri"><span class="subnav-label">ADMIN CONTROL CENTER</span>${acc.map(item).join('')}<span class="subnav-label">AYARLAR</span>${ay.map(item).join('')}</div>`}
function adminLink(title,desc,links){return `<section class="panel settings-section"><h2>${title}</h2><p>${desc}</p><div class="link-grid">${links.map(([h,l])=>`<a class="link-card" href="#${h}">${ic(moduleCatalog.find(m=>m.id===h.split('/')[0])?.icon||'arrow')}<span>${l}</span>${ic('chevron')}</a>`).join('')}</div></section>`}
function adminExec(){const org=state.orgs.find(o=>o.id===state.session.org);return `<section class="metrics">${metric('Aktif müşteri / proje',`${state.clients.filter(c=>c.status==='Aktif'&&!c.internal).length} / ${state.projects.filter(p=>p.status!=='Tamamlandı').length}`,org?.name||'','crm')}${metric('Yaklaşan teslim',state.projects.filter(p=>p.status!=='Tamamlandı'&&daysFromToday(p.due)<=14).length,'14 gün içinde','clock')}${metric('Kârlılık / tahsilat',`%${avgMargin()} · ${money(state.invoices.filter(i=>i.status==='Gecikmiş').reduce((s,i)=>s+i.amount,0))}`,'ort. marj · vadesi geçen','finance')}${metric('Kapasite / açık onay',`%${Math.round(state.team.reduce((s,t)=>s+t.hours,0)/(state.team.length*40)*100)} · ${state.approvals.filter(a=>a.status==='Bekliyor').length}`,'ekip doluluğu · bekleyen onay','approvals')}</section><div class="toolbar filters"><label class="form-field">Şirket<select><option>Tümü</option>${state.orgs.map(o=>`<option>${esc(o.name)}</option>`).join('')}</select></label><label class="form-field">Marka<select><option>Tümü</option>${state.clients.slice(0,6).map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></label><label class="form-field">Birim<select><option>Tümü</option><option>Kreatif</option><option>Müşteri</option><option>Prodüksiyon</option></select></label><label class="form-field">Dönem<select><option>Ekim 2026</option><option>Q4 2026</option></select></label></div><section class="content-grid"><div class="panel"><div class="panel-header"><h2>Riskler</h2></div><div class="panel-body">${[['Kolay İK entegrasyonu hata veriyor','integrations/entegrasyonlar','danger'],['MinIO yedeği 9 gündür doğrulanmadı','admin/health','warn'],['Berke A. hesabı şüpheli giriş sonrası askıda','admin/security','danger'],['Wellana yenileme 30 gün içinde','crm/a360','warn']].map(([t,h,c])=>`<a class="session-row" href="#${h}" style="text-decoration:none"><div>${t}</div>${badge(c==='danger'?'Kritik':'Uyarı',c)}</a>`).join('')}</div></div><div class="panel"><div class="panel-header"><h2>Organizasyonlar</h2></div><div class="panel-body">${state.orgs.map(o=>`<div class="session-row"><div>${esc(o.name)}<small>${esc(o.type)} · ${o.brands} marka · ${o.users} kullanıcı · ${esc(o.plan)}</small></div>${o.id===state.session.org?badge('Seçili','success'):badge('Değiştir','neutral')}</div>`).join('')}</div></div></section>`}
function adminPeople(){return `<section class="panel settings-section"><div class="panel-header" style="padding:0 0 12px"><h2>Kullanıcılar</h2>${btn('Davet gönder','invite-new','sm primary','plus')}</div><div class="table-wrap"><table><thead><tr><th>KULLANICI</th><th>ROL</th><th>SCOPE</th><th>MFA</th><th>OTURUM</th><th>DURUM</th><th></th></tr></thead><tbody>${state.users.map((u,i)=>`<tr><td>${esc(u.name)}<small class="mono">${esc(u.email)}</small></td><td><select data-bind="users.${i}.role" aria-label="${esc(u.name)} rolü" data-rerender>${Object.keys(roleLabel).map(r=>option(r,roleLabel[r],u.role)).join('')}</select></td><td><input data-bind="users.${i}.scope" value="${esc(u.scope)}" aria-label="Scope"></td><td>${u.mfa?badge('MFA açık','success'):badge('MFA yok','warn')}</td><td>${u.sessions} · ${esc(u.last)}</td><td>${badge(u.status)}</td><td><div class="actions">${btn('Oturumları kapat','user-sessions','sm','logout',`data-id="${u.id}"`)}${u.status==='Aktif'?btn('Engelle','user-block','sm danger','close',`data-id="${u.id}"`):btn('Aktif et','user-unblock','sm','check',`data-id="${u.id}"`)}</div></td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:10px">Rol değişikliği owner onayı + MFA ister (own-role escalation engeli). Role template; gerçek yetki organization + product + resource + action + scope bileşimidir.</p></section><section class="panel settings-section"><h2>Davetler</h2>${state.invites.map(i=>`<div class="session-row"><div>${esc(i.email)}<small>${roleLabel[i.role]||i.role} · gönderildi ${esc(i.sent)} · son ${date(i.expires)} · tek kullanımlık süreli token</small></div><div class="actions">${badge(i.status)}${i.status==='Bekliyor'?btn('İptal','invite-cancel','sm danger','close',`data-id="${i.id}"`):btn('Yeniden gönder','invite-resend','sm','refresh',`data-id="${i.id}"`)}</div></div>`).join('')||'<p class="empty">Davet yok.</p>'}</section>`}
function adminCompanies(){return `<section class="panel settings-section"><h2>Organizasyonlar, müşteri şirketleri ve alt markalar</h2><p>Sözleşme–kapsam ilişkisi JS CRM’den okunur; departman/iş birimi etiketleri demo.</p><div class="table-wrap"><table><thead><tr><th>ORGANİZASYON</th><th>MÜŞTERİ ŞİRKETİ</th><th>MARKALAR</th><th>BİRİM</th><th>SÖZLEŞME</th></tr></thead><tbody>${state.clients.map(c=>`<tr><td>${c.internal?'Jobs Studio Grup':'Jobs Studio'}</td><td>${esc(c.name)}${c.internal?' '+badge('Grup','neutral'):''}</td><td>${esc(c.name)}</td><td>${c.sector.includes('Etkinlik')?'Edit Events':'Ajans'}</td><td>${state.contracts.find(x=>x.client===c.id)?badge(state.contracts.find(x=>x.client===c.id).status):badge('Yok','neutral')}</td></tr>`).join('')}</tbody></table></div><div class="form-actions" style="justify-content:start;margin-top:12px">${btn('CRM’de düzenle','goto','','crm','data-id="crm/markalar"')}</div></section>`}
function adminSecurity(){const f=ui.audFilter||'';const ev=state.securityEvents.filter(e=>!f||e.type===f);const types=[...new Set(state.securityEvents.map(e=>e.type))];return `<section class="panel settings-section"><div class="panel-header" style="padding:0 0 12px"><h2>Güvenlik olayları</h2><div class="actions"><select data-ui-sel="audFilter" aria-label="Olay türü"><option value="">Tüm türler</option>${types.map(t=>option(t,t,f)).join('')}</select>${btn('CSV dışa aktar','audit-csv','sm','download')}</div></div><div class="table-wrap"><table><thead><tr><th>ZAMAN</th><th>TÜR</th><th>KİM</th><th>DETAY</th><th></th></tr></thead><tbody>${ev.map(e=>`<tr><td>${esc(e.at)}</td><td>${badge(e.type,e.level==='danger'?'danger':e.level==='warn'?'warn':'neutral')}</td><td class="mono">${esc(e.who)}</td><td>${esc(e.detail)}</td><td>${e.level==='danger'?btn('İncele','sec-investigate','sm','search'):''}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:10px">IP/cihaz bilgileri 180 gün saklanır (Privacy). MFA olayları, rol değişiklikleri, dosya paylaşımı ve hassas veri erişimi ayrıca işaretlenir.</p></section><section class="panel settings-section"><div class="panel-header" style="padding:0 0 12px"><h2>İşlem kaydı (append-only audit)</h2><div class="actions">${badge('Yerel kayıt','neutral')}<input class="field-search" type="search" placeholder="Kayıtlarda ara…" aria-label="İşlem kaydında ara" data-search="audit-rows" data-fn="auditRows" value="${esc(query)}">${btn('CSV','audit-log-csv','sm','download')}</div></div><div class="panel-body" style="padding:0" id="audit-rows">${auditRows()}</div></section>`}
window.auditRows=function(){const q=query.toLocaleLowerCase('tr');return state.audit.filter(e=>e.text.toLocaleLowerCase('tr').includes(q)).slice(0,80).map(e=>`<div class="timeline-entry">${esc(e.text)}<small>${esc(e.at)}${e.who?` · ${esc(e.who)}${e.role?' ('+roleLabel[e.role]+')':''}`:''}</small></div>`).join('')||'<p class="empty">Eşleşen kayıt yok.</p>'};
function adminBilling(){const b=state.billing;const ai=costToday();return `<section class="panel settings-section"><h2>Abonelikler</h2>${b.subs.map(s=>`<div class="toggle-row"><div><strong>${esc(s.name)}</strong><small>${s.used}/${s.seats} kullanıcı · yenileme ${date(s.renew)} · ${esc(s.price)}</small></div>${btn('Yenile','sub-renew','sm','refresh',`data-id="${esc(s.name)}"`)}</div>`).join('')}</section><section class="panel settings-section"><h2>Kotalar</h2><div class="quota-row"><span>Kullanıcı</span>${meter(b.users.used/b.users.quota*100)}<small>${b.users.used} / ${b.users.quota}</small></div><div class="quota-row"><span>Depolama</span>${meter(b.storage.used/b.storage.quota*100)}<small>${b.storage.used} / ${b.storage.quota} TB</small></div><div class="quota-row"><span>AI · bugün</span>${meter(ai/b.ai.capDaily*100,ai/b.ai.capDaily>.8?'danger':'')}<small>${usd(ai)} / ${usd(b.ai.capDaily)}</small></div><div class="quota-row"><span>AI · bu ay</span>${meter(b.ai.monthUsed/b.ai.monthCap*100)}<small>${usd(b.ai.monthUsed)} / ${usd(b.ai.monthCap)}</small></div><p class="small muted" style="margin-top:10px">Maliyet dağılımı: ajanlar %58 · ikizler %27 · Inbox/Studio AI %15. Ürün fiyatları: teyit edilecek.</p></section>`}
function adminHealth(){const h=state.health;const d=state.settings.data;return `<section class="metrics">${metric('İş kuyruğu',h.queue,'bekleyen job','automation')}${metric('API gecikmesi',`${h.latencyMs} <small>ms</small>`,'p95 · 24 saat','cpu')}${metric('API hatası (24s)',h.apiErrors24h,'5xx + webhook retry','flag')}${metric('Erişilebilirlik',h.uptime,'30 gün','globe')}</section><section class="panel settings-section"><h2>Servisler</h2>${[['E-posta senkronu',h.mailSync,'ok'],['Object storage',h.storage,'ok'],['Yedek geri dönüş testi',d.verifyOk?`${d.backupVerified} · doğrulandı`:h.backupRestoreTest,d.verifyOk?'ok':'warn'],['Kolay İK',state.integrations.find(i=>i.id==='kolayik').status,state.integrations.find(i=>i.id==='kolayik').status==='Bağlı'?'ok':'danger']].map(([n,v,l])=>`<div class="toggle-row"><div>${n}<small>${esc(v)}</small></div>${badge(l==='ok'?'Sağlıklı':l==='warn'?'Uyarı':'Hata')}</div>`).join('')}<div class="form-actions" style="justify-content:start">${btn('Yedeği şimdi doğrula','backup-verify',d.verifyOk?'sm':'sm primary','shield')}${btn('Kuyruğu boşalt','queue-flush','sm','play')}</div></section>`}
function adminPrivacy(){const p=state.privacy;return `<section class="panel settings-section"><h2>Saklama (retention)</h2><div class="table-wrap"><table><thead><tr><th>VERİ</th><th>SÜRE</th></tr></thead><tbody>${p.retention.map(([n,v])=>`<tr><td>${n}</td><td>${v}</td></tr>`).join('')}</tbody></table></div></section><section class="panel settings-section"><h2>KVKK talepleri</h2>${p.kvkk.map(k=>`<div class="session-row"><div>${esc(k.who)}<small>${esc(k.type)} · ${esc(k.at)}</small></div><div class="actions">${badge(k.status)}${k.status==='Bekliyor'?btn(k.type.includes('Silme')?'Sil & kapat':'Export üret','kvkk-resolve','sm primary','check',`data-id="${k.id}"`):''}</div></div>`).join('')}<div class="form-actions" style="justify-content:start">${btn('Kişisel veri export (JSON)','export','sm','download')}${btn('Erişim incelemesi başlat','access-review','sm','search')}</div></section><section class="panel settings-section"><h2>Rıza listesi</h2>${p.consents.map(([n,a,b])=>`<div class="quota-row"><span>${n}</span>${meter(a/b*100)}<small>${a} / ${b}</small></div>`).join('')}</section>`}
function adminFlags(){const roles=Object.keys(roleLabel);const mods=moduleCatalog.filter(m=>m.group!=='hidden');return `<section class="panel settings-section"><h2>Modül × rol matrisi</h2><p>Kapalı modül menüde görünmez; API’den de erişilemez. Değişiklik anında menüye yansır.</p><div class="table-wrap"><table class="matrix module-table"><thead><tr><th>MODÜL</th><th>FLAG</th>${roles.map(r=>`<th>${roleLabel[r]}</th>`).join('')}</tr></thead><tbody>${mods.map(m=>`<tr><td>${esc(m.name)}</td><td><input type="checkbox" data-flag="${m.id}" ${state.flags[m.id]!==false?'checked':''} aria-label="${esc(m.name)} flag"></td>${roles.map(r=>`<td><input type="checkbox" data-access="${r}" data-mod="${m.id}" ${state.access[r]?.includes(m.id)?'checked':''} aria-label="${esc(m.name)} · ${roleLabel[r]}"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel settings-section"><h2>Sektör şablonları</h2>${state.sectorTemplates.map((t,i)=>`<div class="toggle-row"><div>${t[0]}<small>${t[1]}</small></div>${sw(`sectorTemplates.${i}.2`,t[2],`${t[0]} şablonu`)}</div>`).join('')}<p class="small muted" style="margin-top:8px">Kontrollü beta: yeni şablon önce tek organizasyonda açılır; kullanım verisiyle genele yayılır.</p></section>`}

/* ---------- Ürünler & Paketler ---------- */
function marketplace(){const parts={paketler:mkPackages,flags:adminFlags};return head('YÖNETİM & SİSTEM · ÜRÜNLER & PAKETLER','Ne kadar gerekiyorsa o kadar.','Ürün paketleri → entitlement → menü. Aynı veri motoru; sektör paketleri şablon ve feature flag varyasyonudur.')+`<div class="toolbar">${subnav()}</div>${(parts[sub]||mkPackages)()}`}
function mkPackages(){return `<div class="project-grid">${state.packages.map((p,i)=>`<article class="panel contract-card ${p.active?'':'off'}"><div class="card-top"><div><h2>${esc(p.name)}</h2><small class="muted">${p.modules.length} modül · Fiyat: teyit edilecek</small></div>${sw(`packages.${i}.active`,p.active,`${p.name} paketi`,'data-package')}</div><p class="small" style="margin:10px 0">${esc(p.desc)}</p><div class="chip-row">${p.modules.map(m=>`<span class="chip ${state.flags[m]===false?'off':''}">${esc(moduleCatalog.find(x=>x.id===m)?.name||m)}</span>`).join('')}</div></article>`).join('')}</div>`}

/* ---------- Uygulamalar ---------- */
function apps(){return head('UYGULAMALAR','Tüm modüller.',`${visibleModules().filter(m=>m.group!=='hidden').length} modül bu rolde açık · ⌘K ile de ulaşabilirsin.`)+`<div class="app-grid">${['main','work','creative','people','intel','manage'].map(g=>{const ms=visibleModules().filter(m=>m.group===g);return ms.length?`<div class="nav-label app-group">${groupLabels[g]}</div>${ms.map(m=>`<a class="app-tile" href="#${m.id}"><span class="app-icon">${ic(m.icon)}</span><strong>${esc(m.name)}</strong><small>${esc(m.desc)}</small>${navCount(m.id)?`<span class="count">${navCount(m.id)}</span>`:''}</a>`).join('')}`:''}).join('')}</div>`}

Object.assign(views,{people,hire,portal,insights,approvals,admin,marketplace,apps});
Object.assign(actions,{
'emp-new'(){openDialog('Personel ekle',`<form class="dialog-body" id="emp-form"><div class="form-grid"><label class="form-field">Ad soyad<input name="name" required></label><label class="form-field">Unvan<input name="title" required></label><label class="form-field">Ekip<select name="team"><option>Kreatif</option><option>Müşteri</option><option>Operasyon</option><option>Prodüksiyon</option></select></label><label class="form-field">Başlangıç<input type="date" name="start" value="2026-11-02"></label></div><div class="form-actions"><button class="button primary" type="submit">Ekle (onboarding başlat) ${ic('plus')}</button></div></form>`)},
'emp-open'(b){empDetail(b.dataset.id)},
'emp-confirm'(b){const e=state.employees.find(x=>x.id===b.dataset.id);if(!e)return;e.status='Aktif';e.leaveTotal=e.leaveTotal||14;done(`${e.name} statüsü teyit edildi.`,`Personel statüsü teyit: ${e.name} → Aktif`)},
'ob-toggle'(b){const e=state.employees.find(x=>x.id===b.dataset.id);const it=e?.[b.dataset.key]?.[Number(b.dataset.i)];if(!it)return;it[1]=!it[1];done(null,`${b.dataset.key==='onboarding'?'Onboarding':'Offboarding'}: ${e.name} · ${it[0]} ${it[1]?'✓':'geri alındı'}`)},
'ho-toggle'(b){const h=state.handover[Number(b.dataset.id)];const it=h?.items[Number(b.dataset.i)];if(!it)return;it[1]=!it[1];done(null,`Devir planı: ${person(h.from)} → ${person(h.to)} · ${it[0]} ${it[1]?'✓':'geri alındı'}`)},
'sign-send-all'(){state.employees.forEach(e=>SIGN_DOCS.forEach(([k])=>{if(e.signatures[k]==='İmza bekliyor')e.signatures[k]='Gönderildi'}));done('İmza seti tüm personele gönderildi (e-imza simülasyonu).','Ekim 2026 imza seti gönderildi.')},
'sign-csv'(){csv('imza-seti.csv',[['Kişi',...SIGN_DOCS.map(d=>d[1])],...state.employees.map(e=>[e.name,...SIGN_DOCS.map(([k])=>e.signatures[k])])]);toast('İmza durumu indiriliyor.')},
'pos-new'(){openDialog('Yeni pozisyon',`<form class="dialog-body" id="pos-form"><div class="form-grid"><label class="form-field">Pozisyon<input name="title" required></label><label class="form-field">Ekip<select name="team"><option>Kreatif</option><option>Müşteri</option><option>Operasyon</option><option>Prodüksiyon</option></select></label><label class="form-field">İşe alım yöneticisi<select name="hm">${state.team.map(t=>option(t.id,t.name)).join('')}</select></label></div><div class="form-actions"><button class="button primary" type="submit">İlanı aç ${ic('plus')}</button></div></form>`)},
'pos-close'(b){const p=state.positions.find(x=>x.id===b.dataset.id);if(!p)return;p.status='Kapalı';done('Pozisyon kapatıldı.',`Pozisyon kapatıldı: ${p.title}`)},
'cand-open'(b){candDetail(b.dataset.id)},
'cand-move'(b){const c=state.candidates.find(x=>x.id===b.dataset.id);if(!c)return;c.stage=b.dataset.to;emit('candidate.stage.changed',`candidate:${c.id}`);done(`→ ${c.stage}`,`Aday aşaması: ${c.name} → ${c.stage}`)},
'cand-score'(b){const c=state.candidates.find(x=>x.id===b.dataset.id);if(!c)return;c.score[b.dataset.k]=Number(b.dataset.n);done(null,`Aday puanı: ${c.name} · ${b.dataset.k} = ${b.dataset.n}`)},
'cand-score-open'(b){closeDialog();ui.cand=b.dataset.id;location.hash='hire/puan'},
'cand-offer'(b){const c=state.candidates.find(x=>x.id===b.dataset.id);done(`${c?.name} için teklif e-postası gönderildi (simülasyon).`,`Teklif gönderildi: ${c?.name}`,false)},
'cand-hire'(b){const c=state.candidates.find(x=>x.id===b.dataset.id);if(!c)return;const pos=state.positions.find(p=>p.id===c.position);if(state.employees.some(e=>e.name===c.name)){toast('Bu aday zaten JS People’da.');return}const id=uid('E');state.employees.push({id,name:c.name,title:pos?.title||'Yeni',team:pos?.team||'Kreatif',start:'2026-11-02',status:'Teyit bekliyor',leaveTotal:14,leaveUsed:0,signatures:sigSet(),onboarding:[['Sözleşme & imza seti (8 belge)',false],['Hesap & erişim (JS Core davet)',false],['Ekipman zimmeti',false],['İlk hafta planı (buddy)',false]]});state.candidates=state.candidates.filter(x=>x.id!==c.id);if(pos){pos.status='Kapalı'}state.invites.unshift({id:uid('in'),email:`${c.name.split(' ')[0].toLocaleLowerCase('tr')}@jobsstudio.example`,role:'creative',sent:now(),expires:'2026-10-21',status:'Bekliyor'});emit('candidate.hired',`candidate:${c.id}`);addNotification(`${c.name} JS People’a aktarıldı; onboarding başladı.`,'people/onboarding');location.hash='people/onboarding';done(`${c.name} JS People’a aktarıldı; onboarding ve davet oluşturuldu.`,`Aday → çalışan: ${c.name} (${pos?.title})`)},
'portal-request'(){location.hash='portal/talep'},
'portal-social-approve'(){const items=state.social.filter(s=>pScope(s.client)&&s.stage==='Müşteri onayı');items.forEach(s=>s.stage='Yayın');state.approvals.filter(a=>a.kind==='Müşteri kararı'&&a.status==='Bekliyor'&&pScope(project(a.project)?.client)&&/takvim|içerik/.test(a.name)).forEach(a=>{a.status='Onaylandı';a.feedback='Portal toplu onay'});emit('client.approval.bulk',`portal:${portalBrands().join(',')}`,'client:'+account().id);done(`${items.length} içerik onaylandı → yayın planına alındı.`,`Portal toplu onay: ${items.length} sosyal içerik (${account().name})`)},
'portal-social-revise'(){const items=state.social.filter(s=>pScope(s.client)&&s.stage==='Müşteri onayı');items.forEach(s=>s.stage='Görsel');done(`${items.length} içerik revizeye döndü.`,`Portal revize: ${items.length} içerik`)},
'portal-download'(b){const a=state.assets.find(x=>x.id===b.dataset.id);emit('file.downloaded',`file:${a?.id}`,'client:'+account().id);state.downloadLog.unshift({at:now(),link:a?.name||'—',who:account().email,ip:'portal',ok:true});done('İmzalı indirme linki üretildi (15 dk).',`Portal indirme: ${a?.name} (${account().name})`,false)},
approve(b){const a=state.approvals.find(x=>x.id===b.dataset.id);if(!a)return;a.status=b.dataset.value;a.decidedAt=now();if(a.status!=='Bekliyor')emit('approval.decided',`approval:${a.id}`);applyApproval(a);done(a.status==='Bekliyor'?'Karar geri alındı.':`Karar: ${a.status}.`,`Onay kararı: ${a.name} → ${a.status}`)},
approval(b){approvalDialog(b.dataset.id)},
'invite-new'(){openDialog('Davet gönder',`<form class="dialog-body" id="invite-form"><p>Süreli, tek kullanımlık token. Davet audit’e yazılır; rol owner onayına tabidir.</p><div class="form-grid"><label class="form-field">E-posta<input type="email" name="email" required placeholder="kisi@jobsstudio.example"></label><label class="form-field">Rol<select name="role">${Object.keys(roleLabel).map(r=>option(r,roleLabel[r],'creative')).join('')}</select></label><label class="form-field full">Scope<input name="scope" value="Atanmış projeler"></label></div><div class="form-actions"><button class="button primary" type="submit">Daveti gönder ${ic('mail')}</button></div></form>`)},
'invite-cancel'(b){const i=state.invites.find(x=>x.id===b.dataset.id);if(!i)return;i.status='İptal edildi';done('Davet iptal edildi.',`Davet iptal: ${i.email}`)},
'invite-resend'(b){const i=state.invites.find(x=>x.id===b.dataset.id);if(!i)return;i.status='Bekliyor';i.sent=now();i.expires='2026-10-21';done('Davet yeniden gönderildi.',`Davet yeniden gönderildi: ${i.email}`)},
'user-sessions'(b){const u=state.users.find(x=>x.id===b.dataset.id);if(!u)return;u.sessions=0;emit('sessions.revoked',`user:${u.id}`);done(`${u.name} oturumları kapatıldı; yeniden doğrulama gerekir.`,`Oturumlar kapatıldı: ${u.email}`)},
'user-block'(b){const u=state.users.find(x=>x.id===b.dataset.id);if(!u)return;u.status='Askıda';u.sessions=0;done('Kullanıcı engellendi.',`Kullanıcı engellendi: ${u.email}`)},
'user-unblock'(b){const u=state.users.find(x=>x.id===b.dataset.id);if(!u)return;u.status='Aktif';done('Kullanıcı aktif edildi.',`Kullanıcı aktif: ${u.email}`)},
'sec-investigate'(){openDialog('Şüpheli deneme',`<div class="dialog-body"><p>berke@jobsstudio.example · 5 başarısız giriş · 45.xx.xx.90 · 14.10 03:12. Hesap otomatik askıya alındı; Berke 30.10’da ayrılıyor.</p><div class="form-actions">${btn('Hesabı kapalı tut','close','primary','check')}</div></div>`)},
'audit-csv'(){csv('guvenlik-olaylari.csv',[['Zaman','Tür','Kim','Detay'],...state.securityEvents.map(e=>[e.at,e.type,e.who,e.detail])]);toast('Güvenlik olayları indiriliyor.')},
'audit-log-csv'(){csv('islem-kaydi.csv',[['Zaman','Kim','Rol','Kayıt'],...state.audit.map(e=>[e.at,e.who||'',e.role||'',e.text])]);toast('İşlem kaydı indiriliyor.')},
'sub-renew'(b){done(`${b.dataset.id} yenileme talebi alındı; fiyat teyit edilecek.`,`Abonelik yenileme talebi: ${b.dataset.id}`,false)},
'queue-flush'(){state.health.queue=0;done('Kuyruk boşaltıldı.','İş kuyruğu boşaltıldı.')},
'kvkk-resolve'(b){const k=state.privacy.kvkk.find(x=>x.id===b.dataset.id);if(!k)return;k.status='Tamamlandı';emit('privacy.request.resolved',`kvkk:${k.id}`);done('KVKK talebi kapatıldı; audit’e yazıldı.',`KVKK talebi tamamlandı: ${k.who} · ${k.type}`)},
'access-review'(){done('Erişim incelemesi başlatıldı: 14 kullanıcı, 3 scope uyarısı.','Erişim incelemesi başlatıldı.',false)},
'insights-weekly'(){download('js-insights-haftalik.txt',`JS INSIGHTS · HAFTALIK ÖZET · W42\n\nPipeline: ${money(state.leads.filter(l=>!['Kazanıldı','Kaybedildi'].includes(l.stage)).reduce((s,l)=>s+l.value,0))}\nOrt. marj: %${avgMargin()}\nRiskli marka: ${state.clients.filter(c=>c.status==='Riskli').map(c=>c.name).join(', ')}\nKurucuya giden karar: ${pendingDecisions()}\n\nE-posta özeti Cuma 17:15 Slack #yonetim + e-posta.`);toast('Haftalık özet indiriliyor; e-posta planlandı.');log('Insights haftalık özet üretildi.')}
});
function applyApproval(a){if(a.status==='Onaylandı'){if(a.task){const t=state.tasks.find(x=>x.id===a.task);if(t)t.stage='Teslim'}if(a.kind==='Kapsam dışı'){const p=project(a.project);p?.scopeChanges?.forEach(s=>{if(s.status==='Bekliyor')s.status='Onaylandı'});state.tasks.filter(t=>t.extra&&t.stage==='Kapsam').forEach(t=>t.stage='Plan');const q=state.quotes.find(x=>x.id==='Q-2026-040');if(q&&a.name.includes('Anova'))q.status='Onaylandı'}if(a.kind==='Bütçe'){state.expenses.filter(x=>x.status==='Onay bekliyor'&&Math.abs(x.amount-a.amount)<1).forEach(x=>x.status='Onaylandı')}if(a.kind==='Yetki değişikliği'){const u=state.users.find(x=>x.name.startsWith('Fatma'));if(u)u.role='manager';state.securityEvents.unshift({at:now(),type:'Rol değişikliği',who:account().email,detail:`${a.name} · onaylandı (MFA)`,level:'warn'})}if(a.kind==='İzin'){state.leaves.filter(l=>l.status==='Bekliyor'&&a.name.includes(person(l.person))).forEach(l=>l.status='Onaylandı')}}}
Object.assign(forms,{
'emp-form'(get){state.employees.push({id:uid('E'),name:get('name'),title:get('title'),team:get('team'),start:get('start'),status:'Teyit bekliyor',leaveTotal:14,leaveUsed:0,signatures:sigSet(),onboarding:[['Sözleşme & imza seti',false],['Hesap & erişim',false],['Ekipman zimmeti',false]]});closeDialog();done('Personel eklendi; onboarding başladı.',`Personel eklendi: ${get('name')}`)},
'pos-form'(get){state.positions.push({id:uid('ps'),title:get('title'),team:get('team'),type:'Tam zamanlı',opened:TODAY,status:'Açık',applicants:0,hiringManager:get('hm')});closeDialog();done('Pozisyon açıldı.',`Pozisyon açıldı: ${get('title')}`)},
'request-form'(get){const r={id:uid('rq'),client:get('client'),title:get('title'),status:'Değerlendiriliyor',created:now(),brief:{goal:get('goal'),audience:get('audience'),outputs:get('outputs'),success:get('success'),limits:get('limits')}};state.requests.unshift(r);state.mails.unshift({id:uid('m'),from:account().name,email:account().email,subject:`[Portal talebi] ${r.title}`,received:now(),status:'Yeni',client:r.client,matched:'portal',threadId:'portal:'+r.id,body:`Hedef: ${r.brief.goal}\nKitle: ${r.brief.audience}\nÇıktılar: ${r.brief.outputs}\nBaşarı: ${r.brief.success}\nSınırlar: ${r.brief.limits}`,attachments:[],drafts:[{unit:'task',type:'Müşteri status raporu',qty:1,title:r.title,owner:'OE',days:3}]});emit('request.created',`request:${r.id}`,'client:'+account().id);addNotification(`Portal talebi: ${r.title} (${client(r.client)})`,'inbox');done('Talep gönderildi; hesap yöneticinize Gelen Kutusu’nda düştü.',`Portal talebi: ${r.title} (${client(r.client)})`)},
'chat-form'(get){state.chat.push({who:'client',text:get('q'),at:now().slice(-5)});state.chat.push({who:'bot',text:portalAnswer(get('q')),at:now().slice(-5)});state.runs.unshift({id:'r'+Date.now(),agent:'Portal asistanı',trigger:'portal:chat',model:state.settings.ai.model,tokens:1900,cost:0.02,status:'Başarılı',at:now()});done(null,`Portal sohbet: ${get('q')}`)},
'approval-form'(get,data,f,e){const decision=e.submitter?.value;const a=state.approvals.find(x=>x.id===f.dataset.id);if(!a)return;const input=f.elements.feedback;if(['Reddedildi','Revizyon'].includes(decision)&&!get('feedback')){input.setCustomValidity('Ret için bir açıklama yaz.');input.reportValidity();input.oninput=()=>input.setCustomValidity('');return}if(decision==='Vekâlet'){if(!get('delegate')){toast('Vekil seç.');return}a.delegate=get('delegate');emit('approval.delegated',`approval:${a.id}`);closeDialog();done(`Vekâlet verildi: ${person(a.delegate)}.`,`Onay vekâleti: ${a.name} → ${person(a.delegate)} (tarih sınırlı, audit)`);return}a.status=decision;a.feedback=get('feedback');a.decidedAt=now();emit('approval.decided',`approval:${a.id}`);applyApproval(a);closeDialog();done(decision==='Onaylandı'?'Onay kaydedildi.':'Ret kaydedildi.',`Onay kararı: ${a.name} → ${decision}${a.feedback?' — '+a.feedback:''} (${account().name}${a.kind==='Yetki değişikliği'?', MFA':''})`)},
'invite-form'(get){state.invites.unshift({id:uid('in'),email:get('email'),role:get('role'),sent:now(),expires:'2026-10-21',status:'Bekliyor'});state.securityEvents.unshift({at:now(),type:'Davet',who:account().email,detail:`${get('email')} · ${roleLabel[get('role')]} · ${get('scope')}`,level:'ok'});emit('invitation.created',`invite:${get('email')}`);closeDialog();done('Davet gönderildi (süreli token).',`Davet gönderildi: ${get('email')} (${roleLabel[get('role')]}, scope: ${get('scope')})`)}
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.flag){state.flags[t.dataset.flag]=t.checked;log(`Feature flag: ${t.dataset.flag} ${t.checked?'açık':'kapalı'}`);toast(`${moduleCatalog.find(m=>m.id===t.dataset.flag)?.name} ${t.checked?'açıldı':'kapatıldı'}.`);render();return}if(t.dataset.access){const r=t.dataset.access,m=t.dataset.mod;const list=state.access[r]||(state.access[r]=[]);if(t.checked){if(!list.includes(m))list.push(m)}else state.access[r]=list.filter(x=>x!==m);log(`Modül erişimi: ${m} · ${roleLabel[r]} ${t.checked?'açık':'kapalı'}`);toast('Erişim matrisi güncellendi.');render()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-package]');if(!b)return;setTimeout(()=>{const i=Number(b.dataset.path.split('.')[1]);const p=state.packages[i];const act=state.packages.filter(x=>x.active).flatMap(x=>x.modules);moduleCatalog.forEach(m=>{if(['overview','profile','apps','admin','marketplace'].includes(m.id))return;state.flags[m.id]=act.includes(m.id)});save();render();toast(`${p.name} ${p.active?'etkin':'devre dışı'} · menü güncellendi.`)},0)});
